/* 系統別評価（基本＋スキルから自動計算） */
function evalsOf(st,sk){return [
 {name:"学業評価",v:Math.round(st.gakuryoku*.7+sk.bungaku*.3)},
 {name:"運動評価",v:Math.round(st.undou*.6+st.tairyoku*.4)},
 {name:"文化評価",v:Math.round((st.geijutsu+sk.ongaku+st.kansei)/3)},
 {name:"社交評価",v:Math.round((st.shakou+st.miryoku+sk.reigi)/3)},
 {name:"生活評価",v:Math.round((sk.ryouri+sk.souji+sk.kidate)/3)}
]}
function rankOf(v){return v>=85?"S":v>=70?"A":v>=55?"B":v>=40?"C":"D"}
const HOKKORI=[
 {id:"hok_cat",title:"子猫と傘",img:"sakura",text:"雨上がりの帰り道、段ボールの中で鳴く子猫を見つけた。\n近くにいた{hero}と一緒に動物病院へ連れて行き、里親が見つかるまで交代で様子を見ることになった。\n「私たち、なんだか家族みたいだね」\n{hero}が笑って、濡れた制服も気にならないくらい、心が温かくなった。"},
 {id:"hok_bento",title:"おにぎりの味",img:"sakura",text:"お昼、財布を忘れて途方に暮れていると、{hero}がおにぎりを半分分けてくれた。\n「お母さんの味なんだ。…内緒だよ？」\n梅干しの酸っぱさと、誰かに分けてもらう嬉しさで、午後も頑張れた気がした。"},
 {id:"hok_granny",title:"坂道の荷物",img:"akari",text:"駅前の急な坂で、重い荷物に困るおばあさんを見かけた。\n{hero}と二人で家まで運ぶと、おばあさんは手作りの麦茶をふるまってくれた。\n「最近の若い子は優しいねえ」\nその一言が、なぜか一日中嬉しかった。"},
 {id:"hok_rain",title:"相合傘",img:"yuki",text:"突然の夕立。傘を忘れた{hero}が軒下で困っていた。\n一本の傘で並んで歩く帰り道。肩が少し濡れたけど、それも悪くないと思った。\n「…ありがとう。今日は、雨に感謝ですね」"},
 {id:"hok_wind",title:"風に飛んだプリント",img:"rin",text:"突風で生徒会のプリントが校庭に散らばった。\n{hero}と二人、夕日の中で一枚一枚拾い集める。\n最後の一枚を拾った時、りんがぽつりと言った。\n「一人じゃなくて、よかった」"},
 {id:"hok_star",title:"帰り道の星空",img:"akari",text:"部活帰り、停電で街の明かりが消えた夜。\n{hero}と見上げた空には、驚くほど星が瞬いていた。\n「たまには、こういうのもいいね」\n何もないはずの帰り道が、特別な思い出になった。"},
 {id:"hok_cookie",title:"手作りクッキー",img:"yuki",text:"放課後、{hero}が少し焦げた手作りクッキーを差し出した。\n「練習したの…。形は悪いけど、味は大丈夫なはず」\n一口食べると、素朴で優しい甘さが広がった。焦げ目まで愛おしい味だった。"},
 {id:"hok_lost",title:"迷子の兄妹",img:"rin",text:"駅前で泣いている小さな兄妹を見つけた。\n{hero}と手をつないで交番まで送り届けると、お母さんが駆けつけて何度も頭を下げた。\n帰り道、「私たち、いいコンビね」と{hero}が微笑んだ。"},
 {id:"hok_ice",title:"帰り道のアイス",img:"akari",text:"真夏の帰り道、駅前のコンビニでアイスを買った。\n{hero}と「どっちの味が当たりか」で真剣に勝負して、負けた方が半分分け合う変なルールになった。\n溶けていくアイスと、溶けない笑顔。夏の放課後は、こうでなくちゃいけない気がした。"},
 {id:"hok_letter",title:"下駄箱の手紙",img:"yuki",text:"下駄箱に、小さな手紙が入っていた。差出人は{hero}。\n『いつもありがとう。言葉だと上手く言えないから、手紙にしました』\nたった3行の手紙を、その日は帰り道に何度も読み返した。"},
 {id:"hok_pudding",title:"放課後プリン",img:"sakura",text:"学食の期間限定プリン、最後の1個。\n{hero}と目が合って、じゃんけんで勝負することになった。\n負けたのに、{hero}はスプーンを2本持ってきた。「半分こが、一番美味しいんだよ」"},
 {id:"hok_snow",title:"雪の日の手袋",img:"yuki",text:"初雪の日、駅までの道で手が悴んだ。\n{hero}が自分の手袋を片方、そっと差し出した。\n「片方ずつで、ちょうどいいんです」\n二人で片方ずつ手袋をして並んで歩く帰り道は、いつもより少し長く感じて、それが嬉しかった。"},
 {id:"hok_tanabata",title:"短冊の願い",img:"rin",text:"七夕の笹に短冊を結ぶ放課後。\n{hero}の短冊が風で裏返って、願い事がちらりと見えた。\n『みんなが笑顔で卒業できますように』\n人の願いを叶えたくなる気持ちが、少しだけ分かった気がした。"},
 {id:"hok_warmcan",title:"温かい缶コーヒー",img:"rin",text:"寒い放課後、自販機の前で手を温めていると、{hero}が温かい缶コーヒーをもう一本買って、そっと渡してくれた。\n「両手で持つと、温かいでしょう」\n何気ない優しさが、夕日の帰り道をずっと温めてくれた。"},
 {id:"hok_flower",title:"押し花の栞",img:"yuki",text:"借りていた本を返すと、中から押し花の栞が落ちた。\n{hero}が言った。「返却を忘れないように、って…。…でも本当は、あなたに持っていてほしくて」\n小さな桜の押し花は、今も大切な本の間に挟まっている。"},
 {id:"hok_dagashi",title:"帰り道の駄菓子屋",img:"sakura",text:"帰り道、小さな駄菓子屋に寄った。\n{hero}と10円ゲームで真剣に勝負して、勝った方がうまい棒を総取りする約束だった。\n結局、二人とも負けて、店のおばあちゃんが笑いながら一本ずつくれた。\n「学生のうちは、それでいいのよ」"},
 {id:"hok_neko",title:"図書室の窓の猫",img:"yuki",text:"図書室の窓の外に、いつも昼寝をしに来る三毛猫がいる。\n{hero}がそっと窓を開けると、猫は伸びをして、本の山の向こうへ消えた。\n「また明日も、来るといいですね」\n静かな午後に、小さな常連さんの話で盛り上がった。"},
 {id:"hok_umbrella",title:"忘れ物の傘",img:"sakura",text:"雨の月曜日、傘立てに先週から残ったままの傘があった。\n{hero}と一緒に持ち主を探して歩き回り、ようやく隣のクラスの子に届けることができた。\n「人の忘れ物を、こんなに探してくれる人、初めてです」\n小さな感謝が、雨の日の憂鬱を晴らしてくれた。"},
 {id:"hok_illumi",title:"点灯前のイルミネーション",img:"rin",text:"冬の放課後、駅前のイルミネーションの点灯準備を手伝うことになった。\n{hero}と脚立に上って電球を一つ一つ確かめ、点灯の瞬間、二人で歓声を上げた。\n「本番より、こっちの方が特別かもね」\n誰も見ていない点灯式が、二人だけの思い出になった。"},
 {id:"hok_senro",title:"線路沿いの夕日",img:"akari",text:"帰り道、線路沿いの土手で夕日が沈むのを見ていた。\n{hero}が隣に座って、買ったばかりの肉まんを半分分けてくれた。\n「夕日って、毎日違う色なんだね」\n何でもない一言が、なぜか胸に残った。明日も、同じ土手を通りたいと思った。"},
 {id:"hok_honno",title:"本の栞の裏",img:"yuki",text:"返してもらった本の栞の裏に、小さな字で一文が書かれていた。\n『今日も隣にいてくれて、ありがとう』\n差出人は{hero}。\n栞一枚で、一週間頑張れる気がした。"},
 {id:"hok_gym",title:"二人三脚の紐",img:"akari",text:"体育祭の練習で、{hero}と二人三脚の紐を結んだ。\n最初は息が合わず何度も転びかけたけれど、肩を組んで歩くうちに、不思議と足並みが揃っていった。\n「卒業までも、こうやって歩けたらいいね」\n{hero}の言葉に、紐より先に心が結ばれた気がした。"},
 {id:"hok_hoshizora",title:"帰り道の流れ星",img:"yuki",text:"少し遅くなった帰り道、{hero}と夜空を見上げていたら、流れ星が一つ、静かに流れた。\n願い事をする間もなかったけれど、二人とも同じ顔をして笑った。\n「言わなくても、同じ願いだったりして」\nそんな他愛ない一言が、帰り道をずっと温かくした。"},
 {id:"hok_seashell",title:"波打ち際の貝殻",img:"akari",text:"海辺で綺麗な貝殻を見つけた。\n{hero}が耳に当てて言った。「波の音、聞こえる？卒業しても、この音は同じだね」\n貝殻は今も、机の一番見える場所に置いてある。"},
 {id:"hok_okayu",title:"看病のおかゆ",img:"sakura",text:"風邪気味で早退した日、{hero}が家までプリントを届けてくれた。\n帰り際、手作りのおかゆの作り方メモまで置いていってくれた。\n不器用な字のメモが、薬より効いた気がした。"},
 {id:"hok_ski_lift",title:"リフトの二人",img:"rin",text:"スキー合宿のリフト。隣に座った{hero}と、眼下の銀世界を見下ろした。\n「高い所って、少しだけ本音が出るよね」\n卒業までの日数を数えて、二人とも少し黙った。"},
 {id:"hok_bookmark2",title:"海辺の栞",img:"yuki",text:"海辺の小さな店で、貝殻の栞を見つけた。\n{hero}が買って、本の間にそっと挟んでくれた。\n「海の物語は、この栞で読みましょう」\n夏の思い出が、本の中で生き続ける気がした。"},
 {id:"hok_muffler",title:"マフラーの片端",img:"sakura",text:"寒い帰り道、{hero}が長いマフラーの片端を、こちらの首にも巻いてくれた。\n半分ずつの温かさで並んで歩く帰り道は、いつもよりゆっくり歩きたくなった。"},
 {id:"hok_hotchoco",title:"雪見ココア",img:"rin",text:"雪の放課後、駅前のカフェで温かいココアを飲んだ。\n{hero}が窓の外の雪を見ながら言った。「卒業しても、雪の日はここで会おう」\n何気ない約束ほど、大事にしたいと思った。"},
 {id:"hok_library",title:"山の形の図書館",img:"yuki",text:"放課後、{hero}に連れられて黒羽図書館へ。\n山みたいな形の建物は、近くで見ると想像よりずっと大きかった。\n「ここ、静かで落ち着くんです。…私の秘密の場所、教えてあげますね」\n窓の外には那珂川。読書の合間に見る景色も、ご褒美みたいだった。"},
 {id:"hok_ayu",title:"鮎の塩焼き",img:"akari",text:"那珂川の河原で、鮎の塩焼きをほおばった。\n「黒羽の鮎は格別だね！」\n{hero}の笑顔と、香ばしい匂いと、川のせせらぎ。\n夏休みって、こういう日のためにあるんだと思った。"},
 {id:"hok_shop",title:"帰りの寄り道",img:"sakura",text:"帰り道、{hero}とダイユーに寄り道。\n明日の材料を買うはずが、気づけばお菓子売り場で長話。\n「リオンドールにも寄る？あっちの方がアイス安いよ」\n何でもない寄り道が、一番楽しかったりする。"}
];
const ALL_MEMORIES=[
 {id:"mem_start",title:"桜の下の再会",date:"4月",hero:"sakura",tag:"物語",text:"桜丘黒羽学園の校門前。舞う桜の中、幼なじみの桜井さくらと再会した。高校生活の3年間が、ここから始まった。"},
 {id:"mem_festival_sport",title:"体育祭のゴールテープ",date:"5月",hero:"akari",tag:"行事",variant:"gym",text:"体育祭のリレー。バトンをつないで駆け抜けた先に、ゴールテープと仲間の歓声があった。あかりの笑顔が、誰より眩しかった。"},
 {id:"mem_test",title:"期末テストの結果",date:"7月",hero:"yuki",tag:"行事",text:"期末テストの返却日。努力の結果が数字になって返ってきた。図書室で一緒に勉強した日々が、静かに報われた気がした。"},
 {id:"mem_summer",title:"夏祭りの夜",date:"8月",hero:"sakura",tag:"行事",variant:"yukata",text:"提灯の明かり、たこ焼きの匂い、遠くの花火。浴衣姿の彼女と歩いた夏祭りの夜は、少しだけ大人になった気分だった。"},
 {id:"mem_culture",title:"文化祭のステージ",date:"10月",hero:"rin",tag:"行事",variant:"gyouji",text:"文化祭のステージ。準備の日々も当日の緊張も、幕が下りた瞬間に全部「やってよかった」に変わった。"},
 {id:"mem_trip",title:"修学旅行の夜",date:"11月",hero:"akari",tag:"行事",text:"修学旅行の夜更かし。布団の上で語り合った将来の夢。窓の外では、知らない街の明かりが静かに瞬いていた。"},
 {id:"mem_xmas",title:"クリスマスの小さな贈り物",date:"12月",hero:"rin",tag:"行事",text:"クリスマスの放課後。ささやかな贈り物を交換した。包みを開ける時の笑顔が、何よりのプレゼントだった。"},
 {id:"mem_valentine",title:"バレンタインのチョコ",date:"2月",hero:"sakura",tag:"行事",text:"下駄箱にそっと置かれた手作りチョコ。添えられた小さなカードには、短いけれど真剣な言葉が書かれていた。"},
 {id:"mem_rooftop_rumor",title:"屋上の伝説",date:"5月",hero:"rin",tag:"物語",text:"「卒業式の日、校舎の屋上で告白すると、その恋は実る」――代々受け継がれる桜丘黒羽学園の神話を聞いた日。屋上への階段は、普段は閉ざされている。"},
 {id:"mem_pool",title:"水泳大会の水しぶき",date:"6月",hero:"akari",tag:"行事",variant:"pool",text:"水泳大会。プールサイドの声援、水しぶき、夏の始まりの匂い。あかりの泳ぎは誰より速くて、誰より楽しそうだった。"},
 {id:"mem_ballgame",title:"球技大会の逆転シュート",date:"5月",hero:"akari",tag:"行事",variant:"gym",text:"球技大会。残り10秒の逆転シュートが決まった瞬間、体育館の歓声が天井を揺らした。あかりとハイタッチした手が、しばらく熱かった。"},
 {id:"mem_marathon",title:"マラソン大会の伴走",date:"1月",hero:"sakura",tag:"行事",variant:"winter",text:"冬のマラソン大会。歩きかけた彼女の隣に、そっと並んで走った。ゴールは一人より、二人の方がずっと近かった。"},
 {id:"mem_sea",title:"海辺の一日",date:"7月",hero:"akari",tag:"行事",variant:"sea",text:"夏休みの海。波打ち際ではしゃぐ声、塩辛い風、少し焼けた肩。夏が永遠に続けばいいのに、と本気で思った一日。"},
 {id:"mem_nurse",title:"看病とおかゆ",date:"9月",hero:"sakura",tag:"ほっこり",variant:"shy",text:"風邪で寝込んだ彼女の家を訪ねた日。冷えピタを貼って、おかゆを作って、「ありがとう」の弱々しい笑顔。看病は、距離が縮まる魔法だった。"},
 {id:"mem_ski",title:"スキー場の転倒",date:"12月",hero:"akari",tag:"行事",variant:"ski",text:"冬のスキー。転んで、笑って、手を取って起き上がる。雪の中で掴んだ手の温かさは、しばらく離れなかった。"},
 {id:"mem_hatsumode",title:"初詣のおみくじ",date:"1月",hero:"yuki",tag:"行事",text:"新年の神社。二人で引いたおみくじと、恋愛成就の祈願。絵馬に書いた願い事は、卒業まで秘密。"},
 {id:"mem_birthday",title:"誕生日の贈り物",date:"いつかの記念日",hero:"sakura",tag:"ほっこり",variant:"smile",text:"彼女の誕生日。覚えていてくれたことが、何よりのプレゼントだと言われた。贈り物より、気持ちが嬉しいのだと知った日。"},
 {id:"mem_whiteday",title:"ホワイトデーのお返し",date:"3月",hero:"sakura",tag:"行事",variant:"shy",text:"バレンタインのお返し。奮発した贈り物を渡すと、彼女は宝物みたいに抱きしめた。卒業まで、あと少し。"},
 {id:"mem_story",title:"彼女の物語",date:"物語",hero:"sakura",tag:"物語",variant:"smile",text:"出会い、すれ違い、小さな秘密、そして本音。彼女との物語は、イベントの寄せ集めじゃない。ちゃんと、心でつながった3年間だった。"},
 {id:"mem_rooftop",title:"屋上の告白",date:"卒業式",hero:"sakura",tag:"エンディング",variant:"ending",text:"卒業式の最後、校舎の屋上。夕日と桜と、3年分の想い。――神話は本当だった。少なくとも、この二人にとっては。"},
 {id:"mem_walkhome",title:"夕日の下校路",date:"4月",hero:"sakura",tag:"物語",variant:"shy",text:"入学してすぐの放課後。夕日の下校路を並んで歩いた日。何気ない帰り道が、物語の始まりだった。"},
 {id:"mem_tanabata",title:"七夕の短冊",date:"7月",hero:"yuki",tag:"行事",variant:"shy",text:"七夕の笹に結んだ短冊。願い事は卒業まで秘密。それでも、隣に立つ人の願いが叶えばいいと、本気で思った夜。"},
 {id:"mem_halloween",title:"ハロウィンの仮装",date:"10月",hero:"rin",tag:"行事",variant:"shy",text:"生徒会主催のハロウィンパーティー。仮装した彼女の、いつもと違う笑顔。お菓子をくれなきゃイタズラする、と本気で言われた気がした。"},
 {id:"mem_snow",title:"雪の日の図書室",date:"12月",hero:"yuki",tag:"ほっこり",variant:"date",text:"雪の日の図書室は、一年で一番静かだった。隣の席で本を読む彼女と、窓の外の雪。何も起きないのに、忘れられない一日。"},
 {id:"mem_aquarium",title:"水族館の夜",date:"8月",hero:"yuki",tag:"行事",variant:"planet",text:"夏の夜の水族館。青い闇の中で光るクラゲと、隣で静かに見上げる彼女。昼とは違う、秘密の世界みたいだった。"},
 {id:"mem_momiji",title:"紅葉と缶コーヒー",date:"11月",hero:"sakura",tag:"ほっこり",variant:"shy",text:"秋の放課後、紅葉の坂道。温かい缶コーヒーを分け合って、他愛ない話をした。何でもない時間が、一番色づいていた。"},
 {id:"mem_yosegaki",title:"卒業アルバムの寄せ書き",date:"3月",hero:"rin",tag:"物語",variant:"smile",text:"卒業アルバムの寄せ書き。彼女の字で書かれた一文――『屋上で、待ってる』。卒業は、もうすぐそこだった。"},
 {id:"mem_sakuratree",title:"伝説の桜の下で",date:"5月",hero:"sakura",tag:"物語",variant:"shy",text:"伝説の桜の下。幼なじみと交わした、小さい頃の約束と、これからの約束。物語は、ここから静かに動き出した。"},
 {id:"mem_cultureprep",title:"文化祭準備の放課後",date:"10月",hero:"rin",tag:"行事",variant:"gyouji",text:"文化祭準備の放課後。段ボールと絵の具と、笑い声。祭りの前のざわめきが、一番楽しかったかもしれない。"},
 {id:"mem_exam",title:"合格お守り",date:"1月",hero:"yuki",tag:"行事",variant:"winter",text:"受験直前。彼女から渡された合格お守り。握りしめるたびに、隣で頑張る人の顔が浮かんだ。"},
 {id:"mem_chocoeve",title:"チョコ作りの試食係",date:"2月",hero:"sakura",tag:"ほっこり",variant:"shy",text:"バレンタイン直前。手作りチョコの試食係に任命された。少し焦げた試作品の味は、なぜか本番より楽しかった。"},
 {id:"mem_speech",title:"弁論大会の壇上",date:"5月",hero:"yuki",tag:"行事",variant:"shy",text:"弁論大会。震える声で始まった彼女の弁論は、最後には会場中を静かにさせた。言葉の力が、人の心を動かした日。"},
 {id:"mem_planetarium",title:"プラネタリウムの約束",date:"8月",hero:"sakura",tag:"デート",variant:"planet",text:"夏のプラネタリウム。暗闇に浮かぶ満天の星と、隣で小さく息をのむ彼女。星より、隣の横顔の方が心に残った。"},
 {id:"mem_illumination",title:"冬のイルミネーション",date:"1月",hero:"rin",tag:"行事",variant:"winter",text:"冬の駅前イルミネーション。光のトンネルの中で、彼女が言った。『点灯の瞬間を一緒に見られて、よかった』。寒さの中の、温かい記憶。"},
 {id:"mem_rainylibrary",title:"梅雨の図書室",date:"6月",hero:"yuki",tag:"ほっこり",variant:"club",text:"梅雨の放課後。雨の音に守られた図書室で、隣の席の彼女と静かに本を読んだ。何も起きない時間が、一番物語みたいだった。"},
 {id:"mem_senko",title:"線香花火の夜",date:"9月",hero:"akari",tag:"行事",variant:"shy",text:"夏の終わりの夕方、河原で線香花火をした。小さい火花が落ちそうで落ちない時間。『なんか、私たちみたいだね』と彼女が笑った。"},
 {id:"mem_concert",title:"秋の音楽室コンサート",date:"11月",hero:"rin",tag:"行事",variant:"club",text:"秋の放課後、音楽室の小さなコンサート。夕日に染まるピアノと、特等席で聴いた一曲。卒業の日に聴かせたい曲の、練習だった。"},
 {id:"mem_setsubun",title:"節分と本気の豆",date:"2月",hero:"rin",tag:"行事",variant:"gyouji",text:"生徒会企画の節分。鬼役を引き受けて、彼女の本気の豆に本気で逃げた。笑い声の響く校舎は、卒業を前に少しだけ賑やかだった。"},
 {id:"mem_gymclass",title:"二人三脚の練習",date:"4月",hero:"akari",tag:"行事",variant:"gym",text:"体育の授業で二人三脚の練習をした日。体操着で肩を組んで、転んで、笑って。足並みが揃った瞬間、二人の距離も少し縮まった気がした。"},
 {id:"mem_study",title:"期末前の勉強会",date:"6月",hero:"yuki",tag:"行事",variant:"club",text:"期末テスト前の図書室勉強会。教え合って、励まし合って、閉館時間まで。勉強だけじゃない何かが、静かに育っていた。"},
 {id:"mem_phone",title:"夏休みの夜の電話",date:"8月",hero:"sakura",tag:"ほっこり",variant:"shy",text:"夏休みの夜、なんでもない用件でかかってきた電話。切るのが惜しくて、他愛ない話が1時間続いた。声だけの距離が、一番近かった夜。"},
 {id:"mem_tripprep",title:"修学旅行のしおり作り",date:"11月",hero:"rin",tag:"行事",variant:"gyouji",text:"修学旅行の班決めとしおり作り。誰と同じ班になるかで、放課後のざわめきが変わった。旅行は、始まる前から始まっていた。"},
 {id:"mem_seaside",title:"海辺の夏服",date:"7月",hero:"akari",tag:"行事",variant:"sea",text:"夏の海辺。水着ではなく夏服で波打ち際を歩いた一日。麦わら帽子と潮風と、彼女の笑顔。夏の思い出は、服が濡れるくらいはしゃいだ方が色濃く残る。"},
 {id:"mem_nurse2",title:"看病と冷えピタ",date:"9月",hero:"akari",tag:"ほっこり",variant:"sick",text:"風邪で寝込んだ彼女のお見舞い。冷えピタとおかゆと、弱々しい「ありがとう」。普段は強がりな彼女の、素直な顔を見た日。"},
 {id:"mem_skirin",title:"雪山の生徒会長",date:"1月",hero:"rin",tag:"行事",variant:"ski",text:"スキー場のりん。赤いウェアにゴーグルを上げて、生徒会長らしくないほど楽しそうに笑っていた。雪山では、誰もが少しだけ子供に戻る。"},
 {id:"mem_seayuki",title:"夕日の海と本",date:"7月",hero:"yuki",tag:"ほっこり",variant:"sea",text:"夕日の海辺で、本を抱えて立つゆき。波の音の中で読む物語と、隣に立つ人の横顔。静かな夏の夕方が、忘れられない1ページになった。"},
 ...HOKKORI.map(h=>({id:h.id,title:h.title,date:"いつかの放課後",hero:h.img,tag:"ほっこり",variant:h.img==="sakura"?"smile":undefined,text:h.text.replaceAll("{hero}","彼女")})),
 {id:"mem_date1",title:"初めてのデート",date:"休日",hero:"sakura",tag:"デート",variant:"date",text:"ドキドキしながら待った待ち合わせ場所。現れた彼女の笑顔を見て、緊張が一気に嬉しさに変わった。"},
 {id:"mem_umbrella",title:"雨の日の相合傘",date:"雨の日",hero:"sakura",tag:"物語",variant:"shy",text:"雨の日の相合傘。二人の距離によって、断られたり、肩が触れたり、手をつながれたり。同じ雨でも、展開は育て方で変わった。"},
 {id:"mem_room",title:"お部屋デート",date:"休日",hero:"sakura",tag:"デート",variant:"date",text:"初めて彼女を自宅に招いた休日。一緒に作ったランチと、何でもない会話。部屋の中の時間は、外のデートとは違う近さがあった。"},
 {id:"mem_visit",title:"お見舞いの温かさ",date:"休養の日",hero:"sakura",tag:"ほっこり",variant:"sick",text:"病気で寝込んだ日、彼女が見舞いに来てくれた。おかゆと心配そうな顔。何よりの薬は、人の温かさだった。"},
 {id:"mem_phone2",title:"電話の向こうの声",date:"いつかの夜",hero:"sakura",tag:"ほっこり",variant:"shy",text:"電話番号を教えてもらってから始まった、夜の電話。他愛ない話が、気づけば長電話になっていた。"},
 {id:"mem_mail",title:"メールのやりとり",date:"いつかの放課後",hero:"yuki",tag:"ほっこり",variant:"smile",text:"メールアドレスを教えてもらった日から、放課後の小さなやりとりが始まった。短い文面の向こうに、彼女の日常が見えた。"},
 {id:"mem_fight",title:"ケンカと仲直り",date:"いつかの放課後",hero:"sakura",tag:"物語",variant:"shy",text:"ケンカして、意地を張って、それでも向き合って仲直りした。ぶつかった分だけ、二人の信頼は深くなった。"},
 {id:"mem_secret",title:"二人だけの秘密",date:"夕方の教室",hero:"yuki",tag:"物語",variant:"shy",text:"夕方の教室で教えてもらった、彼女の秘密。信頼の証を預かる重さと嬉しさは、卒業しても忘れない。"},
 {id:"mem_lostchild",title:"迷子の子供と交番",date:"駅前の休日",hero:"rin",tag:"ほっこり",variant:"smile",text:"駅前で迷子の子供を助けた日。彼女が見ていたのは、結果だけじゃなく、困った人を見捨てない姿勢だった。"},
 {id:"mem_dream",title:"将来の夢を語る夕方",date:"秋の放課後",hero:"rin",tag:"物語",variant:"smile",text:"進路と将来の夢を語り合った夕方。卒業は別れではなく、それぞれの夢への出発なのだと知った日。"},
 {id:"end_friend",title:"エンディング：親友",date:"卒業式",hero:"sakura",tag:"エンディング",variant:"smile",text:"恋人にはならなかったけれど、一生の親友を得た卒業。それも立派な青春の答えだった。"},
 {id:"end_rival",title:"エンディング：ライバル",date:"卒業式",hero:"sakura",tag:"エンディング",variant:"shy",text:"好感度は高かったのに、信頼が届かなかった。恋は好意だけでは実らないと、最後の日に教わった。"},
 {id:"end_life_work",title:"エンディング：仕事成功型",date:"卒業式",hero:"sakura",tag:"エンディング",variant:"grad",text:"学業に打ち込んだ1年が実を結んだ。恋より先に、自分の未来を掴んだ春。"},
 {id:"end_life_hobby",title:"エンディング：趣味没頭型",date:"卒業式",hero:"sakura",tag:"エンディング",variant:"grad",text:"好きな事に没頭した1年。鞄の中の作品ノートの重さが、青春の証だった。"},
 {id:"end_life_friends",title:"エンディング：友人関係充実型",date:"卒業式",hero:"sakura",tag:"エンディング",variant:"grad",text:"友達に囲まれた最高の1年。卒業写真の真ん中の笑顔が、全部を物語っていた。"},
 {id:"end_life_free",title:"エンディング：独身自由人型",date:"卒業式",hero:"sakura",tag:"エンディング",variant:"grad",text:"誰にも縛られない、自由な人生の始まり。卒業は終わりではなく出発だった。"},
 {id:"end_life_none",title:"エンディング：何も成し遂げられなかった型",date:"卒業式",hero:"sakura",tag:"エンディング",variant:"grad",text:"何に打ち込むでもなく過ぎた1年。けれど後悔があるなら、次は変えられる。"},
 {id:"end_money",title:"エンディング：億万長者",date:"卒業式",hero:"sakura",tag:"エンディング",variant:"grad",text:"3年間バイトに全てを捧げた男の通帳には、高校生離れした残高が。恋はなかった。だが、金はある。"},
 {id:"end_host",title:"エンディング：将来のホスト",date:"卒業式",hero:"sakura",tag:"エンディング",variant:"grad",text:"誰とでも打ち解けた3年間。その才能が、新宿の夜で花開く――No.1ホストの伝説の始まり。"},
 {id:"end_star",title:"エンディング：芸能人",date:"卒業式",hero:"sakura",tag:"エンディング",variant:"grad",text:"身だしなみの積み重ねが、駅前のスカウトの目に留まった。桜丘黒羽学園初の芸能人の物語。"},
 {id:"end_journey",title:"エンディング：自分探しの旅",date:"卒業式",hero:"sakura",tag:"エンディング",variant:"grad",text:"何者にもなれなかった春。リュック1つで黒羽駅を発った。続きは、きっとどこかの町で。"},
 {id:"end_sakura",title:"エンディング：さくら",date:"卒業式",hero:"sakura",tag:"エンディング",variant:"ending",text:"卒業式の最後、校舎の屋上で——。"},
 {id:"end_akari",title:"エンディング：あかり",date:"卒業式",hero:"akari",tag:"エンディング",variant:"ending",text:"伝説の桜の木の下で——。"},
 {id:"end_yuki",title:"エンディング：ゆき",date:"卒業式",hero:"yuki",tag:"エンディング",variant:"ending",text:"伝説の桜の木の下で——。"},
 {id:"end_rin",title:"エンディング：りん",date:"卒業式",hero:"rin",tag:"エンディング",variant:"ending",text:"伝説の桜の木の下で——。"},
 {id:"mem_swan",title:"羽田沼の黒い白鳥",date:"月夜",hero:"yuki",tag:"物語",variant:"smile",text:"月夜の羽田沼で、ゆきと黒い白鳥を見た。見た人に幸運を運ぶという、黒羽の言い伝え。二人だけの秘密。"},
 {id:"mem_river",title:"那珂川と鮎の塩焼き",date:"夏",hero:"akari",tag:"物語",variant:"sea",text:"黒羽の那珂川で川遊び。冷たい清流と、香ばしい鮎の塩焼き。彼女の笑顔と一緒に、夏の味がした。"},
 {id:"mem_camp",title:"ホテル花月の合宿",date:"夏",hero:"akari",tag:"物語",variant:"gym",text:"テニス部の合宿先は、町内のホテル花月。日焼けしたあかりと交わした「鮎を食べに行こう」の約束。"},
 {id:"mem_fireworks",title:"くろばね夏まつりの花火",date:"8月",hero:"sakura",tag:"行事",variant:"yukata",text:"芭蕉の里くろばね夏まつりのフィナーレ、市民花火大会。那珂川の水面に映る大輪と、隣の浴衣姿。「来年も、同じ場所で」――夏の約束。"},
 {id:"mem_kuhi",title:"句碑めぐり制覇",date:"黒羽",hero:"yuki",tag:"物語",text:"松尾芭蕉の句碑10か所を、彼女と一緒に全部巡った。常念寺から雲巌寺まで――石に刻まれた句と、隣の笑顔が、黒羽の思い出になった。"},
 {id:"end_solo",title:"エンディング：それぞれの春",date:"卒業式",hero:"sakura",tag:"エンディング",text:"恋だけが青春じゃない。仲間と笑い、努力した1年は、確かに自分のものになった。"}
];

